 1→apiVersion: apps/v1
 2→kind: Deployment
 3→metadata:
 4→  name: {{ include "search-api.fullname" . }}
 5→  labels:
 6→    {{- include "search-api.labels" . | nindent 4 }}
 7→spec:
 8→  {{- if not .Values.autoscaling.enabled }}
 9→  replicas: {{ .Values.replicaCount }}
10→  {{- end }}
11→  selector:
12→    matchLabels:
13→      {{- include "search-api.selectorLabels" . | nindent 6 }}
14→  template:
15→    metadata:
16→      {{- with .Values.podAnnotations }}
17→      annotations:
18→        {{- toYaml . | nindent 8 }}
19→      {{- end }}
20→      labels:
21→        {{- include "search-api.labels" . | nindent 8 }}
22→        {{- with .Values.podLabels }}
23→        {{- toYaml . | nindent 8 }}
24→        {{- end }}
25→    spec:
26→      {{- with .Values.imagePullSecrets }}
27→      imagePullSecrets:
28→        {{- toYaml . | nindent 8 }}
29→      {{- end }}
30→      serviceAccountName: {{ include "search-api.serviceAccountName" . }}
31→      {{- with .Values.podSecurityContext }}
32→      securityContext:
33→        {{- toYaml . | nindent 8 }}
34→      {{- end }}
35→      containers:
36→        - name: {{ .Chart.Name }}
37→          {{- with .Values.securityContext }}
38→          securityContext:
39→            {{- toYaml . | nindent 12 }}
40→          {{- end }}
41→          image: "{{ .Values.image.repository }}:{{ .Values.image.tag | default .Chart.AppVersion }}"
42→          imagePullPolicy: {{ .Values.image.pullPolicy }}
43→          ports:
44→            - name: http
45→              containerPort: {{ .Values.service.port }}
46→              protocol: TCP
47→          {{- with .Values.envFrom }}
48→          envFrom:
49→            {{- toYaml . | nindent 12 }}
50→          {{- end }}
51→          {{- with .Values.env }}
52→          env:
53→            {{- toYaml . | nindent 12 }}
54→          {{- end}}
55→          {{- with .Values.livenessProbe }}
56→          livenessProbe:
57→            {{- toYaml . | nindent 12 }}
58→          {{- end }}
59→          {{- with .Values.readinessProbe }}
60→          readinessProbe:
61→            {{- toYaml . | nindent 12 }}
62→          {{- end }}
63→          {{- with .Values.resources }}
64→          resources:
65→            {{- toYaml . | nindent 12 }}
66→          {{- end }}
67→          {{- with .Values.volumeMounts }}
68→          volumeMounts:
69→            {{- toYaml . | nindent 12 }}
70→          {{- end }}
71→      {{- with .Values.volumes }}
72→      volumes:
73→        {{- toYaml . | nindent 8 }}
74→      {{- end }}
75→      {{- with .Values.nodeSelector }}
76→      nodeSelector:
77→        {{- toYaml . | nindent 8 }}
78→      {{- end }}
79→      {{- with .Values.affinity }}
80→      affinity:
81→        {{- toYaml . | nindent 8 }}
82→      {{- end }}
83→      {{- with .Values.tolerations }}
84→      tolerations:
85→        {{- toYaml . | nindent 8 }}
86→      {{- end }}
