 1→apiVersion: v1
 2→kind: Service
 3→metadata:
 4→  name: {{ include "search-api.fullname" . }}
 5→  labels:
 6→    {{- include "search-api.labels" . | nindent 4 }}
 7→spec:
 8→  type: {{ .Values.service.type }}
 9→  ports:
10→    - port: {{ .Values.service.port }}
11→      targetPort: http
12→      protocol: TCP
13→      name: http
14→  selector:
15→    {{- include "search-api.selectorLabels" . | nindent 4 }}
16→

 1→apiVersion: v1
 2→kind: ConfigMap
 3→metadata:
 4→  name: {{ include "search-api.fullname" . }}-config
 5→  labels:
 6→    {{- include "search-api.labels" . | nindent 4 }}
 7→data:
 8→  # ===== 서비스 특화 설정 (공통 ConfigMap에 없는 것들) =====
 9→  OTEL_SERVICE_NAME: {{ .Values.otelServiceName | quote }}
10→  OTEL_EXPORTER_OTLP_ENDPOINT: {{ .Values.otel.endpoint | quote }}
11→  OTEL_TRACES_EXPORTER: {{ .Values.otel.tracesExporter | quote }}
12→  OTEL_METRICS_EXPORTER: {{ .Values.otel.metricsExporter | quote }}
13→  OTEL_LOGS_EXPORTER: {{ .Values.otel.logsExporter | quote }}
14→  OTEL_INSTRUMENTATION_MICROMETER_ENABLED: {{ .Values.otel.micrometerEnabled | quote }}
15→  JAVA_TOOL_OPTIONS: >
16→    -javaagent:{{ .Values.otel.agentPath }}
17→    -Dotel.experimental.config.file={{ .Values.otel.otelConfig }}
18→
19→  # Search index configuration
20→  SEARCH_INDEX_ADMIN_CATALOG: {{ .Values.config.index.adminCatalog | quote }}
21→  SEARCH_INDEX_ADMIN_PRODUCT: {{ .Values.config.index.adminProduct | quote }}
22→

 1→{{- if .Values.serviceAccount.create -}}
 2→apiVersion: v1
 3→kind: ServiceAccount
 4→metadata:
 5→  name: {{ include "search-api.serviceAccountName" . }}
 6→  labels:
 7→    {{- include "search-api.labels" . | nindent 4 }}
 8→  {{- with .Values.serviceAccount.annotations }}
 9→  annotations:
10→    {{- toYaml . | nindent 4 }}
11→  {{- end }}
12→automountServiceAccountToken: {{ .Values.serviceAccount.automount }}
13→{{- end }}
