 1→{{- if .Values.ingress.enabled -}}
 2→apiVersion: networking.k8s.io/v1
 3→kind: Ingress
 4→metadata:
 5→  name: {{ include "search-api.fullname" . }}
 6→  labels:
 7→    {{- include "search-api.labels" . | nindent 4 }}
 8→  {{- with .Values.ingress.annotations }}
 9→  annotations:
10→    {{- toYaml . | nindent 4 }}
11→  {{- end }}
12→spec:
13→  {{- with .Values.ingress.className }}
14→  ingressClassName: {{ . }}
15→  {{- end }}
16→  {{- if .Values.ingress.tls }}
17→  tls:
18→    {{- range .Values.ingress.tls }}
19→    - hosts:
20→        {{- range .hosts }}
21→        - {{ . | quote }}
22→        {{- end }}
23→      secretName: {{ .secretName }}
24→    {{- end }}
25→  {{- end }}
26→  rules:
27→    {{- range .Values.ingress.hosts }}
28→    - host: {{ .host | quote }}
29→      http:
30→        paths:
31→          {{- range .paths }}
32→          - path: {{ .path }}
33→            {{- with .pathType }}
34→            pathType: {{ . }}
35→            {{- end }}
36→            backend:
37→              service:
38→                name: {{ include "search-api.fullname" $ }}
39→                port:
40→                  number: {{ $.Values.service.port }}
41→          {{- end }}
42→    {{- end }}
43→{{- end }}
44→

 1→1. Get the application URL by running these commands:
 2→{{- if .Values.ingress.enabled }}
 3→{{- range $host := .Values.ingress.hosts }}
 4→  {{- range .paths }}
 5→  http{{ if $.Values.ingress.tls }}s{{ end }}://{{ $host.host }}{{ .path }}
 6→  {{- end }}
 7→{{- end }}
 8→{{- else if contains "NodePort" .Values.service.type }}
 9→  export NODE_PORT=$(kubectl get --namespace {{ .Release.Namespace }} -o jsonpath="{.spec.ports[0].nodePort}" services {{ include "search-api.fullname" . }})
10→  export NODE_IP=$(kubectl get nodes --namespace {{ .Release.Namespace }} -o jsonpath="{.items[0].status.addresses[0].address}")
11→  echo http://$NODE_IP:$NODE_PORT
12→{{- else if contains "LoadBalancer" .Values.service.type }}
13→     NOTE: It may take a few minutes for the LoadBalancer IP to be available.
14→           You can watch its status by running 'kubectl get --namespace {{ .Release.Namespace }} svc -w {{ include "search-api.fullname" . }}'
15→  export SERVICE_IP=$(kubectl get svc --namespace {{ .Release.Namespace }} {{ include "search-api.fullname" . }} --template "{{"{{ range (index .status.loadBalancer.ingress 0) }}{{.}}{{ end }}"}}")
16→  echo http://$SERVICE_IP:{{ .Values.service.port }}
17→{{- else if contains "ClusterIP" .Values.service.type }}
18→  export POD_NAME=$(kubectl get pods --namespace {{ .Release.Namespace }} -l "app.kubernetes.io/name={{ include "search-api.name" . }},app.kubernetes.io/instance={{ .Release.Name }}" -o jsonpath="{.items[0].metadata.name}")
19→  export CONTAINER_PORT=$(kubectl get pod --namespace {{ .Release.Namespace }} $POD_NAME -o jsonpath="{.spec.containers[0].ports[0].containerPort}")
20→  echo "Visit http://127.0.0.1:8080 to use your application"
21→  kubectl --namespace {{ .Release.Namespace }} port-forward $POD_NAME 8080:$CONTAINER_PORT
22→{{- end }}
23→
